function initShareButton(){const t=document.getElementById("share-btn");t&&t.addEventListener("click",()=>{navigator.share?navigator.share({title:document.title,text:"Explore the Police Medal for Gallantry - honoring exceptional courage and bravery.",url:window.location.href}).catch(t=>console.log("Error sharing",t)):navigator.clipboard.writeText(window.location.href).then(()=>{alert("Link copied to clipboard!")})})}document.addEventListener("DOMContentLoaded",()=>{initShareButton()});